// Turns the ONE chat message item (which has multiple binary files
// attached) into N separate items - one per uploaded file - each with
// its binary moved under a single consistent key "data". This is pure
// object re-mapping (no content decoding here), so it works no matter
// how/where the binary content is actually stored.
const item = $input.item;
const binary = item.binary || {};
const keys = Object.keys(binary);
const chatInput = item.json.chatInput || '';

return keys.map((key) => ({
  json: {
    fileName: binary[key].fileName || key,
    chatInput
  },
  binary: {
    data: binary[key]
  }
}));

// Fetches filenames directly from the "Split Attached Files Into Items"
// node (NOT via passthrough, since the native Extract From File node
// strips custom json fields and only keeps its own output field).
// Items stay in the same order through the chain, so index-matching is safe.
const splitItems = $('Split Attached Files Into Items').all();
const extractedItems = $input.all();

let combinedCode = '';
const uploadedFileNames = [];

for (let i = 0; i < extractedItems.length; i++) {
  const fileName = (splitItems[i] && splitItems[i].json && splitItems[i].json.fileName) || `file${i + 1}`;
  const text = extractedItems[i].json.data ?? extractedItems[i].json.text ?? extractedItems[i].json.fileText ?? '';
  uploadedFileNames.push(fileName);
  combinedCode += `--- File: ${fileName} ---\n${text}\n\n`;
}

const chatInput = $('When chat message received').item.json.chatInput || '';

return [{
  json: {
    chatInput,
    combinedCode,
    uploadedFileNames
  }
}];

