// Pulls the extracted file content directly from "Collect Extracted File
// Text" by node reference - this makes it immune to whatever the Framework
// Context Pack (Set) node above does or doesn't pass through.
const collected = $('Collect Extracted File Text').item.json;
const { pageObjectSample, testSpecSample, conventions } = $json;

const frameworkContext = `SAMPLE PAGE OBJECT (reference style):
${pageObjectSample}

SAMPLE TEST SPEC (reference style):
${testSpecSample}

${conventions}`;

return [{
  json: {
    uploadedFileNames: collected.uploadedFileNames,
    frameworkContext,
    combinedCode: collected.combinedCode,
    chatInput: collected.chatInput
  }
}];

