const result = $json.output;

const sevOrder = { High: 0, Medium: 1, Low: 2 };
const findings = result.findings || [];
const correctedFiles = result.correctedFiles || [];

let md = `### Code Review Report\n\n`;
md += `**Overall Summary:** ${result.overallSummary}\n\n`;

if (findings.length === 0) {
  md += `No issues found across any uploaded file.\n\n`;
}

md += `---\n\n`;

for (const file of correctedFiles) {
  const fileFindings = findings
    .filter((f) => f.file === file.fileName)
    .sort((a, b) => (sevOrder[a.severity] ?? 3) - (sevOrder[b.severity] ?? 3));

  md += `## File: ${file.fileName}\n\n`;

  if (fileFindings.length === 0) {
    md += `No issues found in this file.\n\n`;
  } else {
    md += `**Issues found (${fileFindings.length}):**\n\n`;
    for (const f of fileFindings) {
      md += `- [${f.id}] (${f.category} / ${f.severity}) ${f.issue}\n`;
      md += `  - Why: ${f.explanation}\n`;
      md += `  - Fix applied: ${f.suggestedFix}\n\n`;
    }
  }

  md += `**What changed in this file & why:** ${file.summaryOfChanges}\n\n`;
  md += `Corrected file \`${file.fileName}\` is attached below.\n\n`;
  md += `---\n\n`;
}

const binary = {};
correctedFiles.forEach((file, idx) => {
  binary['correctedFile' + idx] = {
    data: Buffer.from(file.correctedCode, 'utf-8').toString('base64'),
    mimeType: 'text/plain',
    fileName: file.fileName,
    fileExtension: (file.fileName.split('.').pop() || 'txt')
  };
});

return [{ json: { output: md }, binary }];
